const V = (x,y,z)=>new THREE.Vector3(x,y,z);
const COL = { blue:0x6f9fd8, red:0xd98a8a, orange:0xf2a33c, axis:0x111111, arrow:0x888888 };

// lighting
scene.add(new THREE.AmbientLight(0xffffff,0.65));
const dl = new THREE.DirectionalLight(0xffffff,0.7); dl.position.set(3,5,4); scene.add(dl);
const dl2 = new THREE.DirectionalLight(0xffffff,0.35); dl2.position.set(-3,-2,-4); scene.add(dl2);

function stdMat(color, emissive=0.12){
  return new THREE.MeshStandardMaterial({color, emissive:color, emissiveIntensity:emissive,
    roughness:0.45, metalness:0.05, side:THREE.DoubleSide});
}

// ---- axis triad per panel ----
function makeAxes(c, len=0.5){
  const dirs = { x:V(1,0,0), y:V(0,0,1), z:V(0,1,0) };
  const up = V(0,1,0);
  for(const key of ['x','y','z']){
    const d = dirs[key];
    const geo = new THREE.BufferGeometry().setFromPoints([c.clone().add(d.clone().multiplyScalar(-len)), c.clone().add(d.clone().multiplyScalar(len))]);
    scene.add(new THREE.Line(geo, new THREE.LineBasicMaterial({color:COL.axis})));
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.045,0.12,8), new THREE.MeshBasicMaterial({color:COL.axis}));
    cone.position.copy(c.clone().add(d.clone().multiplyScalar(len)));
    cone.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(up, d.clone().normalize()));
    scene.add(cone);
    addLabel('<i>'+key+'</i>', c.clone().add(d.clone().multiplyScalar(len+0.16)), {fontSize:'10px', color:'#111'});
  }
}

// ---- teardrop hybrid lobe (deformed sphere about local +Z, then oriented) ----
function makeTeardrop(dirWorld, Rfront, Rback, color){
  const geo = new THREE.SphereGeometry(1,28,28);
  const pos = geo.attributes.position;
  for(let i=0;i<pos.count;i++){
    const n = V(pos.getX(i),pos.getY(i),pos.getZ(i)).normalize();
    const t = n.z; // -1..1 along local lobe axis
    const r = Rback + (Rfront-Rback)*Math.pow((t+1)/2, 1.6);
    pos.setXYZ(i, n.x*r, n.y*r, n.z*r);
  }
  pos.needsUpdate=true; geo.computeVertexNormals(); geo.computeBoundingSphere();
  const mesh = new THREE.Mesh(geo, stdMat(color));
  mesh.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(V(0,0,1), dirWorld.clone().normalize()));
  return mesh;
}

// ---- p dumbbell (two ellipsoids) ----
function makeDumbbell(c, axisWorld, len=0.34, rad=0.13){
  const g = new THREE.Group();
  const a = axisWorld.clone().normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(V(0,1,0), a);
  for(const s of [1,-1]){
    const geo = new THREE.SphereGeometry(1,20,20);
    geo.scale(rad, len, rad);
    const m = new THREE.Mesh(geo, stdMat(s>0?COL.blue:COL.red));
    m.position.copy(c.clone().add(a.clone().multiplyScalar(s*len*0.78)));
    m.quaternion.copy(q);
    g.add(m);
  }
  scene.add(g);
  return g;
}

