function makeArrow(c, dir, len, color){
  const g = new THREE.Group();
  const d = dir.clone().normalize();
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.035,0.035,len,10), new THREE.MeshBasicMaterial({color}));
  cyl.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(V(0,1,0), d));
