// Element spec (world frame: source-x→+X, source-z→+Y(up), source-y→+Z(depth);
//  OBLIQUE projection renders +Z as the up-right screen diagonal, matching the source):
//  s orbital        → SphereGeometry(0.26) blue #6f9fd8, vertex highlight
//  p_x/p_y/p_z      → 2 ellipsoids (SphereGeometry scaled) blue(+)/red(−) dumbbell
//  4 hybrid lobes   → deformed SphereGeometry TEARDROP (big round front + tiny back),
//                     vertex-color gradient yellow-tip→orange-body, narrow tip at centre
//  tetrahedral      → 4 teardrops offset outward along sp³ dirs (distinct, not fused)
//  axis triads      → 3 black Lines + ConeGeometry arrowheads per panel + x,y,z labels
//  process arrows   → grey Cylinder+Cone ("Hybridization" →, "Gives a tetrahedral arrangement" ↓)

const V = (x,y,z)=>new THREE.Vector3(x,y,z);
const COL = { blue:0x6f9fd8, red:0xd98a8a, orange:0xf2a33c, axis:0x111111, arrow:0x8a8a8a };

scene.add(new THREE.AmbientLight(0xffffff,0.7));
const dl = new THREE.DirectionalLight(0xffffff,0.85); dl.position.set(3,6,4); scene.add(dl);
const dl2 = new THREE.DirectionalLight(0xffffff,0.35); dl2.position.set(-4,-2,-3); scene.add(dl2);

function stdMat(color, emissive=0.10, vertexColors=false){
  return new THREE.MeshStandardMaterial({
    color: vertexColors?0xffffff:color,
    emissive: color, emissiveIntensity: emissive,
    roughness:0.42, metalness:0.04, side:THREE.DoubleSide,
    vertexColors
  });
}

// ---- axis triad (y labelled on the up-right / world -Z end so oblique shows it diagonal) ----
function makeAxes(c, len=0.46){
  const lineDirs = { x:V(1,0,0), y:V(0,0,1), z:V(0,1,0) };
  const labelDirs = { x:V(1,0,0), y:V(0,0,-1), z:V(0,1,0) };
  const up = V(0,1,0);
  for(const key of ['x','y','z']){
    const ld = lineDirs[key];
    const geo = new THREE.BufferGeometry().setFromPoints(
      [c.clone().add(ld.clone().multiplyScalar(-len)), c.clone().add(ld.clone().multiplyScalar(len))]);
    scene.add(new THREE.Line(geo, new THREE.LineBasicMaterial({color:COL.axis})));
    const ad = labelDirs[key];
    const cone = new THREE.Mesh(new THREE.ConeGeometry(0.04,0.11,8), new THREE.MeshBasicMaterial({color:COL.axis}));
    cone.position.copy(c.clone().add(ad.clone().multiplyScalar(len)));
    cone.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(up, ad.clone().normalize()));
    scene.add(cone);
    addLabel('<i>'+key+'</i>', c.clone().add(ad.clone().multiplyScalar(len+0.15)), {fontSize:'10px', color:'#111'});
  }
}

// ---- teardrop hybrid lobe: big round front (+localZ), tiny back; tip shifted to local origin ----
function teardropGeometry(Rfront, Rback, gradient){
  const geo = new THREE.SphereGeometry(1,30,30);
  const pos = geo.attributes.position;
  const colors = new Float32Array(pos.count*3);
  const cBack = new THREE.Color(0xe07a1f);   // deep orange body/back
  const cFront = new THREE.Color(0xffd27a);  // light yellow highlight at the bulb
  for(let i=0;i<pos.count;i++){
    const n = V(pos.getX(i),pos.getY(i),pos.getZ(i)).normalize();
    const t = n.z;                                  // -1 (back) .. +1 (front)
    const u = (t+1)/2;
    const r = Rback + (Rfront-Rback)*Math.pow(u, 2.4);   // sharp exponent → real teardrop
    let x=n.x*r, y=n.y*r, z=n.z*r + Rback;               // shift so back tip sits at local 0
    pos.setXYZ(i,x,y,z);
    if(gradient){
      const cc = cBack.clone().lerp(cFront, Math.pow(u,1.4));
      colors[i*3]=cc.r; colors[i*3+1]=cc.g; colors[i*3+2]=cc.b;
    }
  }
  pos.needsUpdate=true;
  if(gradient) geo.setAttribute('color', new THREE.BufferAttribute(colors,3));
  geo.computeVertexNormals(); geo.computeBoundingSphere();
  return geo;
}
function makeTeardrop(dirWorld, Rfront, Rback, gradient){
  const mesh = new THREE.Mesh(teardropGeometry(Rfront,Rback,gradient), stdMat(COL.orange,0.12,gradient));
  mesh.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(V(0,0,1), dirWorld.clone().normalize()));
  return mesh;
}

// ---- p dumbbell (two opposite-phase ellipsoids) ----
function makeDumbbell(c, axisWorld, len=0.34, rad=0.125){
  const g = new THREE.Group();
  const a = axisWorld.clone().normalize();
  const q = new THREE.Quaternion().setFromUnitVectors(V(0,1,0), a);
  for(const s of [1,-1]){
    const geo = new THREE.SphereGeometry(1,22,22); geo.scale(rad,len,rad);
    const m = new THREE.Mesh(geo, stdMat(s>0?COL.blue:COL.red,0.14));
    m.position.copy(c.clone().add(a.clone().multiplyScalar(s*len*0.8)));
    m.quaternion.copy(q); g.add(m);
  }
  scene.add(g); return g;
}

// ===================== LEFT: atomic orbitals =====================
const P = { s:V(-3.4,1.4,0), px:V(-2.0,1.4,0), py:V(-3.4,-0.6,0), pz:V(-2.0,-0.6,0) };
makeAxes(P.s); makeAxes(P.px); makeAxes(P.py); makeAxes(P.pz);

const sMesh = new THREE.Mesh(new THREE.SphereGeometry(0.26,30,30), stdMat(COL.blue,0.18));
sMesh.position.copy(P.s); scene.add(sMesh);
registerInteractive(sMesh,{title:'s orbital',tooltip:'s orbital (spherical)',
  body:'The s orbital is spherically symmetric — equal in every direction. Mixed with the three p orbitals it gives each hybrid a large front lobe and a small back lobe.'});

const pxG = makeDumbbell(P.px, V(1,0,0));
registerInteractive(pxG,{title:'p_x orbital',tooltip:'p_x (along x)',
  body:'p_x has two opposite-phase lobes along the x-axis (blue +, red −), supplying x-directionality to the hybrids.'});
const pyG = makeDumbbell(P.py, V(0,0,1));
registerInteractive(pyG,{title:'p_y orbital',tooltip:'p_y (along y)',
  body:'p_y has two opposite-phase lobes along the y-axis (the diagonal here), supplying y-directionality.'});
const pzG = makeDumbbell(P.pz, V(0,1,0));
registerInteractive(pzG,{title:'p_z orbital',tooltip:'p_z (along z)',
  body:'p_z has two opposite-phase lobes along the z-axis, supplying z-directionality.'});

addLabel('<i>s</i>',   P.s.clone().add(V(0,-0.55,0)),  {fontSize:'14px',bold:true});
addLabel('<i>p</i><sub>x</sub>', P.px.clone().add(V(0,-0.55,0)), {fontSize:'14px',bold:true});
addLabel('<i>p</i><sub>y</sub>', P.py.clone().add(V(0,-0.55,0)), {fontSize:'14px',bold:true});
addLabel('<i>p</i><sub>z</sub>', P.pz.clone().add(V(0,-0.55,0)), {fontSize:'14px',bold:true});

// ===================== process arrow: Hybridization =====================
function makeArrow(c, dir, len, color){
  const g = new THREE.Group(); const d = dir.clone().normalize();
  const cyl = new THREE.Mesh(new THREE.CylinderGeometry(0.035,0.035,len,10), new THREE.MeshBasicMaterial({color}));
  cyl.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(V(0,1,0), d));
  cyl.position.copy(c.clone().add(d.clone().multiplyScalar(len/2)));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.09,0.22,12), new THREE.MeshBasicMaterial({color}));
  cone.quaternion.copy(new THREE.Quaternion().setFromUnitVectors(V(0,1,0), d));
  cone.position.copy(c.clone().add(d.clone().multiplyScalar(len+0.1)));
  g.add(cyl,cone); scene.add(g); return g;
}
makeArrow(V(-1.15,1.4,0), V(1,0,0), 0.7, COL.arrow);
addLabel('Hybridization', V(-0.75,1.9,0), {fontSize:'14px',bold:true});

// ===================== RIGHT: 4 hybrid teardrops =====================
const H = [
  {c:V(1.2, 1.4,0), dir:V(0, 1,0)},
  {c:V(2.6, 1.4,0), dir:V(1, 0,0)},
  {c:V(1.2,-0.6,0), dir:V(-1,0,0)},
  {c:V(2.6,-0.6,0), dir:V(0,-1,0)},
];
let RBACK = 0.08; const RFRONT = 0.5;
const hybridMeshes = [];
for(const h of H){
  makeAxes(h.c, 0.46);
  const m = makeTeardrop(h.dir, RFRONT, RBACK, true);
  m.position.copy(h.c); scene.add(m); hybridMeshes.push(m);
  registerInteractive(m,{title:'sp³ hybrid orbital',tooltip:'one sp³ hybrid (teardrop)',
    body:'Mixing s + p_x + p_y + p_z with this sign pattern yields one strongly directional lobe: a large front bulb and a small back lobe. Four equivalent hybrids point to the corners of a tetrahedron.'});
}
function refreshHybrids(){
  hybridMeshes.forEach((m,i)=>{
    const old=m.geometry; m.geometry=teardropGeometry(RFRONT,RBACK,true); old.dispose();
  });
}

// ===================== bottom: tetrahedral arrangement =====================
makeArrow(V(2.6,-1.35,0), V(0,-1,0), 0.5, COL.arrow);
addLabel('Gives a tetrahedral<br>arrangement', V(3.6,-1.55,0), {fontSize:'13px',bold:true});

const TC = V(2.6,-3.0,0);
makeAxes(TC, 0.55);
// sp³ dirs in source (x,y,z) → world (X=sx, Y=sz, Z=-sy)
const sp3src = [V(1,1,1),V(1,-1,-1),V(-1,1,-1),V(-1,-1,1)];
const tetraGroup = new THREE.Group();
for(const s of sp3src){
  const dw = V(s.x, s.z, -s.y).normalize();
  const m = makeTeardrop(dw, 0.46, 0.10, true);
  m.position.copy(TC.clone().add(dw.clone().multiplyScalar(0.16))); // spread lobes apart
  tetraGroup.add(m);
}
scene.add(tetraGroup);
registerInteractive(tetraGroup,{title:'Tetrahedral sp³ set',tooltip:'4 hybrids → tetrahedron (109.5°)',
  body:'The four equivalent sp³ hybrids point toward the corners of a regular tetrahedron, separated by 109.5° — the geometry of methane and other sp³ centres.'});

// ===================== camera (oblique: depth = up-right diagonal) =====================
function applyView(target, hf){
  setCameraView({ projection:'oblique', obliqueAngleDeg:45, depthScale:0.55,
    azimuthDeg:90, elevationDeg:0, heightFraction:hf, target });
}
applyView([-0.3,-0.8,0], 0.92);

// ===================== UI =====================
const views = {
  All:    {target:[-0.3,-0.8,0], hf:0.92},
  Atomic: {target:[-2.7, 0.4,0], hf:0.62},
  Hybrid: {target:[ 1.9, 0.4,0], hf:0.62},
  Tetra:  {target:[ 2.6,-3.0,0], hf:0.55},
};
function focus(name){
  const v = views[name]; applyView(v.target, v.hf);
  document.querySelectorAll('.step-btn').forEach(b=>b.classList.remove('active'));
  const btn = document.getElementById('btn'+name); if(btn) btn.classList.add('active');
}
document.getElementById('btnAll').addEventListener('click',()=>focus('All'));
document.getElementById('btnAtomic').addEventListener('click',()=>focus('Atomic'));
document.getElementById('btnHybrid').addEventListener('click',()=>focus('Hybrid'));
document.getElementById('btnTetra').addEventListener('click',()=>focus('Tetra'));
document.getElementById('rngBack').addEventListener('input', e=>{
  RBACK = parseFloat(e.target.value); refreshHybrids();
});
// @FIGURE_CODE_END

